COMMENT ON COLUMN EMPLOYEE.EMPLOYEE_ID IS 'the unique id for the employee';
COMMENT ON COLUMN EMPLOYEE.FIRST_NAME IS 'first name of the employee';
COMMENT ON COLUMN EMPLOYEE.LAST_NAME IS 'last name of the employee';
ALTER TABLE EMPLOYEE MODIFY (LAST_NAME ANNOTATIONS (ADD value_description 'commonsense evidence: full name: first name + last_name'));
COMMENT ON COLUMN EMPLOYEE.ADDRESS IS 'physical street address of the employee';
COMMENT ON COLUMN EMPLOYEE.CITY IS 'city of the employee''s address';
COMMENT ON COLUMN EMPLOYEE.STATE IS 'state of the customer''s address';
COMMENT ON COLUMN EMPLOYEE.ZIP IS 'postal code of the employee''s address';
COMMENT ON COLUMN EMPLOYEE.PHONE IS 'telephone number to reach the customer';
COMMENT ON COLUMN EMPLOYEE.TITLE IS 'career title of the employee';
ALTER TABLE EMPLOYEE MODIFY (TITLE ANNOTATIONS (ADD value_description ' Sanitarian  Supervisor  Division Manager'));
COMMENT ON COLUMN EMPLOYEE.SALARY IS 'the salary of the employee';
ALTER TABLE EMPLOYEE MODIFY (SALARY ANNOTATIONS (ADD value_description 'us dollars / yearcommonsense evidence: monthly salary: salary / 12'));
COMMENT ON COLUMN EMPLOYEE.SUPERVISOR IS 'the employee id of the employee''s supervisor';
COMMENT ON COLUMN ESTABLISHMENT.LICENSE_NO IS 'the license number of the facility';
COMMENT ON COLUMN ESTABLISHMENT.DBA_NAME IS 'the dba name of the facility';
ALTER TABLE ESTABLISHMENT MODIFY (DBA_NAME ANNOTATIONS (ADD value_description 'commonsense evidence: DBA stands for doing business as. It''s also referred to as your business''s assumed, trade or fictitious name.'));
COMMENT ON COLUMN ESTABLISHMENT.AKA_NAME IS 'the aka name of the facility';
ALTER TABLE ESTABLISHMENT MODIFY (AKA_NAME ANNOTATIONS (ADD value_description 'commonsense evidence: the aka name is used to indicate another name that a person or thing has or uses'));
COMMENT ON COLUMN ESTABLISHMENT.FACILITY_TYPE IS 'the facility type';
ALTER TABLE ESTABLISHMENT MODIFY (FACILITY_TYPE ANNOTATIONS (ADD value_description 'commonsense evidence: can ask some questions about its categories, for i.e.:  "Restaurant" and "Cafeteria" refers to restaurants  PASTRY school and "CULINARY ARTS SCHOOL" belongs to "Education" or "School". Please design this and mention your evidence in the commonsense part of questions, thanks'));
COMMENT ON COLUMN ESTABLISHMENT.RISK_LEVEL IS 'the risk level of the facility';
ALTER TABLE ESTABLISHMENT MODIFY (RISK_LEVEL ANNOTATIONS (ADD value_description 'commonsense evidence: Facilities with higher risk level have more serious food safety issues'));
COMMENT ON COLUMN ESTABLISHMENT.ADDRESS IS 'physical street address of the facility';
COMMENT ON COLUMN ESTABLISHMENT.CITY IS 'city of the facility''s address';
COMMENT ON COLUMN ESTABLISHMENT.STATE IS 'state of the facility''s address';
COMMENT ON COLUMN ESTABLISHMENT.ZIP IS 'postal code of the facility''s address';
COMMENT ON COLUMN ESTABLISHMENT.LATITUDE IS 'the latitude of the facility';
COMMENT ON COLUMN ESTABLISHMENT.LONGITUDE IS 'the longitude of the facility';
ALTER TABLE ESTABLISHMENT MODIFY (LONGITUDE ANNOTATIONS (ADD value_description 'commonsense evidence: location = POINT(latitude, longitude)'));
COMMENT ON COLUMN ESTABLISHMENT.WARD IS 'the ward number of the facility';
ALTER TABLE ESTABLISHMENT MODIFY (WARD ANNOTATIONS (ADD value_description 'commonsense evidence: Ward number is the number assigned by the local authorities to identify the population count in each town, village and district usually for electoral purposes or to extract property and locality details'));
COMMENT ON COLUMN INSPECTION.INSPECTION_ID IS 'the unique id for the inspection';
COMMENT ON COLUMN INSPECTION.INSPECTION_DATE IS 'the date of the inspection';
ALTER TABLE INSPECTION MODIFY (INSPECTION_DATE ANNOTATIONS (ADD value_description 'yyyy-mm-dd'));
COMMENT ON COLUMN INSPECTION.INSPECTION_TYPE IS 'the type of the inspection';
COMMENT ON COLUMN INSPECTION.RESULTS IS 'the inspection results';
ALTER TABLE INSPECTION MODIFY (RESULTS ANNOTATIONS (ADD value_description ' Pass  Pass w/ Conditions  Fail  Out of Business  Business Not Located  No Entry  Not Ready commonsense evidence: the quality is verified: Pass + Pass w/ Conditions'));
COMMENT ON COLUMN INSPECTION.EMPLOYEE_ID IS 'the id of the employee who is responsible for the inspection';
COMMENT ON COLUMN INSPECTION.LICENSE_NO IS 'the license number of the facility that is inspected';
COMMENT ON COLUMN INSPECTION.FOLLOWUP_TO IS 'the id of inspections that this inspection is following up';
ALTER TABLE INSPECTION MODIFY (FOLLOWUP_TO ANNOTATIONS (ADD value_description 'commonsense evidence: ''No data'' means the inspection has no followup.if followup_to has value:  it''s the parent inspection id, and this value represents child inspection id  the entire inspection: followup_to + inspection_id'));
COMMENT ON COLUMN INSPECTION_POINT.POINT_ID IS 'the unique id for the inspection point';
COMMENT ON COLUMN INSPECTION_POINT.DESCRIPTION IS 'the specific description of the inspection results';
COMMENT ON COLUMN INSPECTION_POINT.CATEGORY IS 'the inspection category';
COMMENT ON COLUMN INSPECTION_POINT.CODE IS 'the sanitary operating requirement code';
ALTER TABLE INSPECTION_POINT MODIFY (CODE ANNOTATIONS (ADD value_description 'commonsense evidence: Each code stands for an operating requirement'));
COMMENT ON COLUMN INSPECTION_POINT.FINE IS 'the fines for food safety problems';
ALTER TABLE INSPECTION_POINT MODIFY (FINE ANNOTATIONS (ADD value_description 'commonsense evidence: The fine of more serious food safety problems will be higher.  Minor: 100  Serious: 250  Critical: 500'));
COMMENT ON COLUMN INSPECTION_POINT.POINT_LEVEL IS 'point level';
ALTER TABLE INSPECTION_POINT MODIFY (POINT_LEVEL ANNOTATIONS (ADD value_description 'Critical / Serious/ Minor'));
COMMENT ON COLUMN VIOLATION.INSPECTION_ID IS 'the unique id for the inspection';
COMMENT ON COLUMN VIOLATION.POINT_ID IS 'the inspection point id';
COMMENT ON COLUMN VIOLATION.FINE IS 'the fine of the violation';
ALTER TABLE VIOLATION MODIFY (FINE ANNOTATIONS (ADD value_description 'commonsense evidence: The fine of more serious food safety problems will be higher.  Minor: 100  Serious: 250  Critical: 500'));
COMMENT ON COLUMN VIOLATION.INSPECTOR_COMMENT IS 'the comment of the inspector';